# Review questions per chapter: list of (question, answer)
QA = {
 1: [("마이크로서비스의 핵심 특징 두 가지는?", "독립적으로 배포·확장할 수 있는 작은 서비스로 나뉘고, 각 서비스가 자신의 데이터를 소유하며 API로만 통신한다."),
     ("분산 시스템에서 '네트워크는 신뢰할 수 있다'는 가정이 위험한 이유는?", "호출이 지연·실패·중복될 수 있어서, 타임아웃·재시도·회로 차단기 같은 대비가 없으면 장애가 연쇄적으로 퍼진다(13장)."),
     ("에지 서버 패턴이 푸는 문제는?", "외부에 공개할 API만 한 진입점으로 노출하고 내부 서비스는 숨기며, 인증·라우팅 같은 공통 기능을 한곳에서 처리한다(10장).")],
 2: [("스프링 부트의 자동 구성은 어떻게 동작하나?", "클래스패스에 있는 라이브러리와 설정 값을 조건으로 필요한 빈을 자동으로 등록한다. 이 저장소의 Boot 4에서는 자동 구성이 기능별 모듈로 나뉘어, 기능마다 해당 스타터가 필요하다."),
     ("Mono와 Flux의 차이는?", "Mono는 0~1개, Flux는 0~N개의 값을 비동기로 내보내는 반응형 타입이다."),
     ("스프링 클라우드 스트림을 쓰는 이유는?", "RabbitMQ·Kafka 같은 메시징 시스템의 차이를 바인더 뒤로 숨기고, 함수(Consumer 등)와 설정만으로 메시지를 주고받게 해 준다.")],
 3: [("api 모듈과 util 모듈을 나눈 이유는?", "서비스 사이에 공유하는 API 인터페이스·DTO(api)와 공통 기능(util: 예외 처리, 서비스 주소)을 한곳에 두어 중복을 줄이기 위해서다."),
     ("product-composite는 핵심 서비스가 404를 돌려주면 어떻게 처리하나?", "`ProductCompositeIntegration`이 HTTP 오류를 `NotFoundException` 등으로 바꾸고, `GlobalControllerExceptionHandler`가 같은 상태 코드의 JSON 오류로 응답한다."),
     ("이 저장소에서 422 상태 코드를 가리키는 상수는?", "`HttpStatus.UNPROCESSABLE_CONTENT`. Spring Framework 7에서 `UNPROCESSABLE_ENTITY`에서 이름이 바뀌었다.")],
 4: [("Dockerfile을 두 단계로 나누고 레이어를 추출하는 이유는?", "의존성처럼 잘 바뀌지 않는 부분을 별도 레이어로 두어, 애플리케이션 코드만 바뀌었을 때 이미지 빌드와 전송을 빠르게 하기 위해서다."),
     ("`docker` 스프링 프로필은 무엇을 바꾸나?", "컨테이너 환경에 맞게 포트와 다른 서비스의 호스트 이름(서비스 이름) 등을 바꾼다."),
     ("`test-em-all.bash start stop`은 무엇을 하나?", "도커 컴포즈로 시스템을 띄우고, 전체 테스트를 실행한 뒤 시스템을 내린다.")],
 5: [("API 설명을 애너테이션에 직접 쓰지 않고 application.yml에 두는 이유는?", "코드 변경 없이 문서를 고칠 수 있고, 긴 설명으로 코드가 지저분해지는 것을 막기 위해서다."),
     ("Swagger UI는 어떤 경로로 열리나?", "product-composite의 `/openapi/swagger-ui.html`(설정의 `springdoc.swagger-ui.path`).")],
 6: [("product·recommendation과 review가 다른 데이터베이스를 쓰는 이유는?", "서비스마다 데이터를 독립적으로 소유하고, 문서형(MongoDB)과 관계형(MySQL) 저장소를 모두 다뤄 보기 위해서다."),
     ("엔티티에 `@Version` 필드를 두는 이유는?", "낙관적 잠금으로 동시 수정 충돌을 감지하기 위해서다(영속성 테스트의 낙관적 잠금 검사)."),
     ("Testcontainers를 쓰면 무엇이 좋은가?", "테스트 중에 실제 MongoDB·MySQL 컨테이너를 띄워 운영과 같은 데이터베이스로 영속성 코드를 검증할 수 있다.")],
 7: [("review 서비스의 JPA 호출은 반응형 코드에서 어떻게 처리하나?", "블로킹 호출을 별도 스케줄러(`jdbcScheduler`)에서 실행해 이벤트 루프 스레드를 막지 않는다."),
     ("생성·삭제를 이벤트로 처리할 때 장점과 대가는?", "호출한 쪽이 핵심 서비스의 장애와 지연에 덜 묶이지만, 결과가 바로 반영되지 않는 최종 일관성을 감수해야 한다."),
     ("데드 레터 큐(DLQ)는 언제 쓰이나?", "재시도 후에도 처리하지 못한 메시지를 따로 보관해 나중에 분석·재처리할 수 있게 한다.")],
 8: [("2부에서 추가되는 스프링 클라우드 구성 요소를 장별로 나열하면?", "9장 유레카(서비스 검색), 10장 게이트웨이(에지 서버), 11장 인가 서버(보안), 12장 컨피그 서버(구성 중앙화), 13장 Resilience4j(탄력성), 14장 Micrometer Tracing + Zipkin(분산 추적).")],
 9: [("클라이언트 측 로드 밸런싱이란?", "호출하는 쪽(product-composite)이 유레카에서 받은 인스턴스 목록 중 하나를 골라 직접 호출하는 방식이다."),
     ("인스턴스를 늘렸을 때 바로 호출에 반영되지 않는 이유는?", "유레카 등록과 클라이언트 캐시 갱신에 시간이 걸리기 때문이다. `test-em-all.bash`도 등록이 끝날 때까지 기다린다.")],
 10: [("게이트웨이 뒤로 서비스를 숨기면 얻는 것은?", "외부 진입점이 하나가 되어 보안·라우팅을 한곳에서 관리하고, 내부 서비스는 외부에 직접 노출되지 않는다."),
      ("라우트의 술어(predicate)와 필터의 차이는?", "술어는 어떤 요청이 그 라우트에 해당하는지 판단하고, 필터는 요청·응답을 바꾸거나(경로 재작성 등) 부가 처리를 한다.")],
 11: [("접근 토큰의 스코프는 어디서 검사하나?", "product-composite(리소스 서버)의 보안 설정에서 경로·메서드별로 `SCOPE_product:read` 같은 권한을 검사한다."),
      ("Spring Boot 4에서 리소스 서버를 쓰려면 필요한 스타터는?", "`spring-boot-starter-security-oauth2-resource-server`. 리소스 서버 자동 구성이 별도 모듈로 분리됐다."),
      ("스코프가 없는 토큰으로 쓰기 API를 호출하면?", "인증은 되지만 권한이 없어 403 Forbidden을 받는다.")],
 12: [("config-repo의 application.yml과 서비스별 파일의 관계는?", "application.yml은 모든 서비스에 공통으로 적용되고, 서비스 이름의 파일(예: product-composite.yml)이 그 위에 덮어쓴다."),
      ("컨피그 서버를 쓸 때 시작 순서 문제는 어떻게 다루나?", "클라이언트가 컨피그 서버에 연결될 때까지 재시도한다(fail-fast + spring-retry 설정).")],
 13: [("회로 차단기가 OPEN일 때 호출은 어떻게 되나?", "실제 호출을 하지 않고 바로 실패 처리되어 폴백 메서드가 응답을 만든다. 일정 시간 뒤 HALF_OPEN에서 시험 호출을 한다."),
      ("시간 제한과 재시도를 함께 쓸 때 주의할 점은?", "재시도 횟수×대기 시간이 전체 응답 시간을 늘리고, 실패한 서비스에 부하를 더할 수 있으므로 회로 차단기와 함께 신중히 설정한다."),
      ("이 저장소에서 `circuitbreakerevents`의 상태 전환이 `CLOSED_TO_OPEN`으로 나오도록 한 설정은?", "`spring.jackson.datatype.enum.write-enums-using-to-string: false`. Jackson 3는 기본으로 enum을 `toString()`으로 쓰기 때문이다.")],
 14: [("trace ID와 span ID의 차이는?", "trace ID는 요청 하나가 거치는 전체 흐름을, span ID는 그 안의 개별 작업(서비스 호출 하나 등)을 식별한다."),
      ("메시지로 처리되는 비동기 작업도 같은 추적에 묶이는 이유는?", "메시지 헤더에 추적 컨텍스트가 실려 전달되기 때문이다."),
      ("Boot 4에서 Zipkin 엔드포인트를 지정하는 프로퍼티는?", "`management.tracing.export.zipkin.endpoint`.")],
 15: [("디플로이먼트를 쓰면 파드를 지웠을 때 어떻게 되나?", "레플리카셋이 원하는 개수를 맞추기 위해 새 파드를 다시 만든다."),
      ("서비스(Service) 객체의 역할은?", "바뀌는 파드 IP 대신 고정된 이름과 주소로 파드 묶음에 접근하게 하고, 트래픽을 분산한다.")],
 16: [("헬름의 common 차트를 라이브러리 차트로 둔 이유는?", "디플로이먼트·서비스·컨피그맵 템플릿을 한곳에 두고 각 컴포넌트 차트가 재사용해 중복을 없애기 위해서다."),
      ("liveness와 readiness 프로브의 차이는?", "liveness 실패 시 컨테이너를 재시작하고, readiness 실패 시 트래픽만 보내지 않는다."),
      ("정상 종료(graceful shutdown)를 켜는 이유는?", "파드가 내려갈 때 처리 중인 요청을 끝낸 뒤 종료해, 롤링 업데이트 중 요청 실패를 줄이기 위해서다.")],
 17: [("17장에서 쿠버네티스 기능으로 대체한 스프링 클라우드 구성 요소 세 가지는?", "컨피그 서버 → 컨피그맵·시크릿, 유레카 → 쿠버네티스 서비스, 게이트웨이 → Ingress."),
      ("cert-manager가 하는 일은?", "Ingress에 쓸 TLS 인증서를 자동으로 발급·갱신한다(이 책에서는 자체 서명 발급자).")],
 18: [("사이드카 프록시를 쓰면 코드 변경 없이 얻는 것은?", "mTLS 암호화, 트래픽 제어(라우팅·재시도·장애 주입), 메트릭·추적 같은 관찰 가능성."),
      ("블루/그린 배포에서 VirtualService의 역할은?", "v1과 v2 사이에 트래픽 비율이나 특정 헤더 기준 라우팅을 정해, 새 버전으로 점진적으로 넘어가게 한다."),
      ("장애 주입을 실습하는 이유는?", "의존 서비스가 실패·지연될 때 회로 차단기와 재시도가 의도대로 동작하는지 실제 환경에서 확인하기 위해서다.")],
 19: [("Fluentd가 로그를 Elasticsearch에 넣기 전에 하는 일은?", "컨테이너 로그를 모아 형식(자바 로그, 이스티오 접근 로그)에 맞게 파싱하고 필드를 붙인다."),
      ("추적 ID를 로그에 남기면 무엇이 좋은가?", "Kibana에서 trace ID 하나로 여러 서비스의 로그를 묶어 요청 흐름 전체를 볼 수 있다.")],
 20: [("Prometheus는 메트릭을 어떻게 가져오나?", "각 서비스의 `/actuator/prometheus` 엔드포인트를 주기적으로 긁어(pull) 간다."),
      ("회로 차단기 상태를 대시보드로 볼 수 있는 이유는?", "Resilience4j가 Micrometer로 상태·호출 수 메트릭을 내보내기 때문이다.")],
 21: [("이 저장소 실습에 필요한 JDK 버전은?", "JDK 21. 교재는 24를 쓰지만 이 저장소는 Java 21로 옮겨져 있다.")],
 22: [("WSL 2 환경에서 Docker를 쓸 때 확인할 것은?", "WSL 2 배포판 안에서 `docker version`과 `docker compose version`이 동작하는지, 메모리 할당이 충분한지 확인한다.")],
 23: [("네이티브 이미지에서 리플렉션 힌트가 필요한 이유는?", "빌드 시점에 도달 가능한 코드만 포함하는 닫힌 세계 가정 때문에, 실행 중 리플렉션으로 쓰는 클래스를 미리 알려 줘야 한다."),
      ("Spring Boot 4 네이티브 이미지에 필요한 GraalVM 버전은?", "GraalVM 25 이상. 이 저장소는 빌드팩에 `BP_JVM_VERSION=25`를 지정한다."),
      ("네이티브 이미지의 장단점은?", "기동이 빠르고 메모리를 적게 쓰지만, 빌드가 오래 걸리고 리플렉션·동적 기능에 제약이 있다.")],
}
